1: const express = require('express');
2: const cors = require('cors');
3: const bodyParser = require('body-parser');
4: const fs = require('fs');
5: const path = require('path');
6: const app = express();
7: 
8: // route modules imports
9: const authRoutes = require('./routes/auth');
10: const homeRoutes = require('./routes/home');
11: const organizationRoutes = require('./routes/organizations');
12: const teamRoutes = require('./routes/teams');
13: const repositoryRoutes = require('./routes/repositories');
14: 
15: // middleware imports
16: app.use(cors());
17: app.use(bodyParser.json());
18: 
19: // API answers are never cached, so a reload always sees the latest stored state.
20: app.use('/api', (req, res, next) => {
21:   res.set('Cache-Control', 'no-store');
22:   next();
23: });
24: 
25: // API requests are handled one at a time in arrival order, so a write sent just before a page reload is
26: // stored before the reload's reads run. A request whose connection already closed is skipped (res.closed;
27: // not req.destroyed, which newer Node versions set as soon as body-parser has read the body).
28: // A request still running after API_SLOT_MS lets later requests through, so one handler that never
29: // answers cannot stall every other request.
30: const API_SLOT_MS = 10000;
31: let apiQueue = Promise.resolve();
32: app.use('/api', (req, res, next) => {
33:   apiQueue = apiQueue.then(() => new Promise((resolve) => {
34:     if (res.closed) {
35:       resolve();
36:       return;
37:     }
38:     const timer = setTimeout(() => {
39:       console.error(`[api] ${req.method} ${req.originalUrl} has not answered after ${API_SLOT_MS} ms`);
40:       resolve();
41:     }, API_SLOT_MS);
42:     const release = () => {
43:       clearTimeout(timer);
44:       resolve();
45:     };
46:     res.on('finish', release);
47:     res.on('close', release);
48:     next();
49:   }));
50: });
51: 
52: // Startup work. index.js starts listening only after app.ready resolves, so chain every startup step
53: // (schema, seed data) onto this promise instead of starting it in the background.
54: const { initializeDatabase } = require('./database/init_db');
55: const seedDatabase = require('./database/seed_db');
56: app.ready = initializeDatabase().then(() => seedDatabase());
57: 
58: // register routes
59: app.use('/api', authRoutes);
60: app.use('/api', homeRoutes);
61: app.use('/api', organizationRoutes);
62: app.use('/api', teamRoutes);
63: app.use('/api', repositoryRoutes);
64: 
65: app.get('/api/health', (req, res) => {
66:   res.json({ code: 200, message: 'Backend Ready' });
67: });
68: 
69: // Uncaught errors from the page (see frontend/src/main.tsx), logged for the check tool.
70: app.post('/api/client-errors', (req, res) => {
71:   const { message = '', page = '' } = req.body || {};
72:   console.error(`[browser error] ${String(page).slice(0, 200)} ${String(message).slice(0, 500).replace(/\s+/g, ' ')}`);
73:   res.status(204).end();
74: });
75: 
76: const frontendDistPath = path.resolve(__dirname, '../../frontend/dist');
77: 
78: if (fs.existsSync(frontendDistPath)) {
79:   app.use(express.static(frontendDistPath));
80: 
81:   // Keep API routes on the backend and serve the SPA for all other GET requests.
82:   app.get(/^(?!\/api(?:\/|$)).*/, (req, res) => {
83:     res.sendFile(path.join(frontendDistPath, 'index.html'));
