27: function hashPassword(pw) {
28:   const salt = crypto.randomBytes(16).toString('hex');
29:   const hash = crypto.createHash('sha256').update(salt + String(pw)).digest('hex');
30:   return `${salt}:${hash}`;
31: }
32: function verifyPassword(pw, stored) {
33:   const [salt, hash] = String(stored).split(':');
34:   if (!salt || !hash) return false;
35:   return crypto.createHash('sha256').update(salt + String(pw)).digest('hex') === hash;
36: }
