158:     let current = '';
159:     while (pos < expr.length && expr[pos] !== ')') {
160:       const ch = expr[pos];
161:       if (ch === ',') {
162:         refs.push(current); current = '';
163:         pos++;
164:         continue;
165:       }
166:       current += ch;
167:       pos++;
168:     }
169:     if (current) refs.push(current);
170:     const out = [];
171:     for (const r of refs) {
172:       const colon = r.indexOf(':');
173:       if (colon > 0) {
174:         const a = parseRef(r.slice(0, colon));
175:         const b = parseRef(r.slice(colon + 1));
176:         if (!a || !b) throw new Error('bad range ' + r);
177:         for (let ri = Math.min(a.row, b.row); ri <= Math.max(a.row, b.row); ri++) {
178:           for (let ci = Math.min(a.col, b.col); ci <= Math.max(a.col, b.col); ci++) {
179:             out.push(colLetter(ci) + (ri + 1));
180:           }
181:         }
182:       } else {
183:         if (!parseRef(r)) throw new Error('bad ref ' + r);
184:         out.push(r.toUpperCase().replace(/\$/g, ''));
185:       }
186:     }
187:     return out;
188:   }
189:   function parsePrimary() { return parseValue(); }
190:   function parseMulDiv() {
191:     let left = parsePrimary();
192:     while (pos < expr.length && (expr[pos] === '*' || expr[pos] === '/')) {
193:       const op = expr[pos]; pos++;
194:       const right = parsePrimary();
195:       // ����Ϊ 0�����ո������˻��ɵ� 0���� #DIV/0!�������� Infinity
196:       if (op === '/' && right === 0) throw new FormulaError(ERR_DIV0);
197:       left = op === '*' ? left * right : left / right;
198:     }
