200:   }
201:   function parseAddSub() {
202:     let left = parseMulDiv();
203:     while (pos < expr.length && (expr[pos] === '+' || expr[pos] === '-')) {
204:       const op = expr[pos]; pos++;
205:       const right = parseMulDiv();
206:       left = op === '+' ? left + right : left - right;
207:     }
208:     return left;
209:   }
210:   function parseExpr() { return parseAddSub(); }
211:   return parseExpr();
212: }
