410: // ��/�в�����insert/delete������ cells��
411: function remapAxis(cells, axis, op, index, ws) {
412:   const out = {};
413:   for (const [cell, v] of Object.entries(cells)) {
414:     const p = parseRef(cell);
415:     if (!p) continue;
416:     let row = p.row + 1; // 1-based
417:     let col = p.col;     // 0-based
418:     let dCol = 0;
419:     let dRow = 0;
420:     if (axis === 'row') {
421:       if (op === 'insert' && row >= index) { row += 1; dRow = 1; }
422:       else if (op === 'delete') {
423:         if (row === index) continue;
424:         if (row > index) { row -= 1; dRow = -1; }
425:       }
426:     } else {
427:       if (op === 'insert' && col >= index) { col += 1; dCol = 1; }
428:       else if (op === 'delete') {
429:         if (col === index) continue;
430:         if (col > index) { col -= 1; dCol = -1; }
431:       }
432:     }
433:     if (row < 1 || col < 0 || col >= 26) continue;
434:     const nv = { ...v };
435:     // ��ʽ���������/ɾ��ƽ�ƣ�REQ-2-2-1 ����4 / REQ-2-2-2 ����4��
436:     if (isFormulaCell(nv)) nv.raw = shiftFormula(nv.raw, dCol, dRow);
437:     out[colLetter(col) + row] = nv;
438:   }
439:   // ������֤���������/ɾ��ƽ�ƣ�REQ-2-2-1 ����5��Խ��ֵ�뱻���ƺ�Ĺ������أ�
440:   // ע�⣺����������ǡ���Ԫ���ַ�������'A2'�������� {row,col} ���� ������ parseRef ������
441:   if (ws && Array.isArray(ws.validations)) {
442:     ws.validations = ws.validations.map((r) => {
443:       const ps = parseRef(r.start);
444:       const pe = parseRef(r.end);
445:       if (!ps || !pe) return r;
446:       let r1 = ps.row + 1;   // 1-based
447:       let c1 = ps.col;       // 0-based
448:       let r2 = pe.row + 1;
449:       let c2 = pe.col;
450:       if (axis === 'row') {
451:         if (op === 'insert' && r1 >= index) { r1 += 1; r2 += 1; }
452:         else if (op === 'delete') {
453:           if (r1 <= index && index <= r2) return null; // ɾ�����򸲸��� �� ����ʧЧ
454:           if (r1 > index) { r1 -= 1; r2 -= 1; }
455:         }
456:       } else {
457:         if (op === 'insert' && c1 >= index) { c1 += 1; c2 += 1; }
458:         else if (op === 'delete') {
459:           if (c1 <= index && index <= c2) return null;
460:           if (c1 > index) { c1 -= 1; c2 -= 1; }
461:         }
462:       }
463:       if (r1 < 1 || c1 < 0 || r2 < 1 || c2 < 0 || r2 < r1 || c2 < c1) return null;
464:       return {
465:         ...r,
466:         start: colLetter(c1) + r1,
467:         end: colLetter(c2) + r2,
468:         id: `dv-${colLetter(c1) + r1}-${colLetter(c2) + r2}`,
469:       };
470:     }).filter(Boolean);
471:   }
472:   return out;
473: }
