483: // ��ȡ��ʽ��ĵ�Ԫ�����ã��� shiftFormula ͬ�ھ��� A1 / $A$1 �Ǻţ�
484: // �ۺϺ���������� '(' �������֣��ʲ��ᱻ�������������У�
485: function formulaDeps(raw) {
486:   const body = String(raw).slice(1);
487:   const re = /(\$?)([A-Za-z]{1,2})(\$?)(\d+)/g;
488:   const out = [];
489:   let m;
490:   while ((m = re.exec(body)) !== null) {
491:     const key = m[0].toUpperCase().replace(/\$/g, '');
492:     const p = parseRef(key);
493:     out.push(p ? colLetter(p.col) + (p.row + 1) : key);
494:   }
