502: // ȫ�����㣨REQ-4-2-2����
503: //   1) ֻ���㹫ʽ��Ԫ�� ���� �ǹ�ʽ��� value ��������д�뷽��õ�ֵ��������δ
504: //      trim �� raw���纬 \r �Ŀ�ֵ��д�� value����Ⱦ�ۺϺ�����"���Կյ�Ԫ��"�ж���
505: //   2) ����ѭ�����ü�⣨������ B5=B5����� A1=B1/B1=A1 ���㣩�����и��� #REF!��
506: //   3) ���ఴ����������һ����ֵ������̬ͨ�� FormulaError ����������������
507: function recalcDeep(ws) {
508:   const keys = Object.keys(ws.cells).filter((k) => isFormulaCell(ws.cells[k]));
509:   const keySet = new Set(keys);
510:   const deps = {};
511:   for (const k of keys) deps[k] = formulaDeps(ws.cells[k].raw).filter((d) => keySet.has(d));
512: 
513:   // 1) ѭ�����ã�DFS + ��ջ���ر�ָ���ջ�����ζ���ѭ��
514:   const state = {};
515:   const circular = new Set();
516:   const stack = [];
517:   const visit = (u) => {
518:     state[u] = 1;
519:     stack.push(u);
520:     for (const v of deps[u]) {
521:       if (state[v] === 1) {
522:         const i = stack.indexOf(v);
523:         for (let j = (i < 0 ? 0 : i); j < stack.length; j += 1) circular.add(stack[j]);
524:       } else if (!state[v]) {
525:         visit(v);
526:       }
527:     }
528:     stack.pop();
529:     state[u] = 2;
530:   };
531:   for (const k of keys) if (!state[k]) visit(k);
532: 
533:   // 2) �������������㣬��ѭ����һ������
534:   const order = [];
535:   const seen = {};
536:   const topo = (u) => {
537:     if (seen[u]) return;
538:     seen[u] = 1;
539:     for (const v of deps[u]) if (!circular.has(v)) topo(v);
540:     order.push(u);
541:   };
542:   for (const k of keys) if (!circular.has(k)) topo(k);
543: 
544:   const readVal = (ref) => {
545:     const p = parseRef(ref);
546:     if (!p) return '';
547:     const dep = ws.cells[colLetter(p.col) + (p.row + 1)];
548:     return dep ? (dep.value ?? '') : '';
549:   };
550:   for (const k of circular) ws.cells[k].value = ERR_REF;
551:   for (const k of order) ws.cells[k].value = evalFormula(ws.cells[k].raw, readVal);
552: }
