554: // ��ʽ����ƽ�ƣ�������ð� (dCol,dRow) ƫ�ƣ��������ã��� $�����ֲ���
555: function shiftFormula(raw, dCol, dRow) {
556:   if (typeof raw !== 'string' || !raw.startsWith('=')) return raw;
557:   return raw.replace(/(\$?)([A-Za-z]{1,2})(\$?)(\d+)/g, (m, absC, col, absR, row) => {
558:     let c = colIndex(col);
559:     let r = Number(row);
560:     if (!absC) c += dCol;
561:     if (!absR) r += dRow;
562:     if (c < 0 || r < 1) return '#REF!';
563:     return absC + colLetter(c) + absR + r;
564:   });
565: }
