675: // RFC4180 ��������֧�����Ű����Ķ���/���С�ת��˫����("")��CRLF/LF ��β��
676: // ����ǰ���㣨ԭ�Ĳ�ת���֣������ֶ�=�մ���δ�պ����ŵȽṹ���� �� ok:false
677: function parseCsvText(text) {
678:   const src = String(text ?? '').replace(/^\uFEFF/, '');
679:   const rows = [];
680:   let row = [];
681:   let field = '';
682:   let inQuotes = false;
683:   let i = 0;
684: 
685:   while (i < src.length) {
686:     const ch = src[i];
687:     if (inQuotes) {
688:       if (ch === '"') {
689:         if (src[i + 1] === '"') { field += '"'; i += 2; continue; }
690:         inQuotes = false; i += 1; continue;
691:       }
692:       field += ch; i += 1; continue;
693:     }
694:     if (ch === '"') {
695:       // ����ֻ�ܳ������ֶ���ʼ����������Ϊ�Ƿ��ṹ
696:       if (field !== '') return { ok: false };
697:       inQuotes = true; i += 1; continue;
698:     }
699:     if (ch === ',') { row.push(field); field = ''; i += 1; continue; }
700:     if (ch === '\r' || ch === '\n') {
701:       if (ch === '\r' && src[i + 1] === '\n') i += 1;
702:       row.push(field); field = ''; rows.push(row); row = []; i += 1; continue;
703:     }
704:     field += ch; i += 1;
705:   }
706:   // δ�պ����ţ��� `Alex,"unfinished quote`���� �Ƿ� CSV
707:   if (inQuotes) return { ok: false };
708:   if (field !== '' || row.length > 0) { row.push(field); rows.push(row); }
709:   return { ok: true, rows };
710: }
