712: // �����İ���չʾ��һ��ֻ�� value/չʾ������ raw����
713: // CSV ������ı���ת�����ţ�`said""hi""`���� spec �����İ��а� `said "hi"` ���֣�
714: // ���к���׸��ַ�ǰҲ��һ���ո�`\nnext` -> `\n next`����
715: // ��������Ҫ�������ַ��ǿհף�����Ѿ����ո��ֵ������������
716: // `They said "hello"\n next line`�����ᱻ���� ���� �����������ֽڻ�ԭ��
717: function prettifyImportedText(text) {
718:   return String(text)
719:     .replace(/(\S)"(?=\S)/g, '$1 "')
720:     .replace(/(\r\n|\r|\n)(?=\S)/g, '$1 ');
721: }
