728: // ��ǰ������ -> CSV��ֻȡ��ʹ�����򣬹�ʽ��Ԫ�񵼳�**������**
729: function worksheetToCsv(ws) {
730:   const cells = ws?.cells || {};
731:   let maxRow = 0;
732:   let maxCol = 0;
733:   for (const key of Object.keys(cells)) {
734:     const p = parseRef(key);
735:     if (!p) continue;
736:     if (String(cells[key]?.raw ?? '') === '') continue;
737:     if (p.row + 1 > maxRow) maxRow = p.row + 1;
738:     if (p.col + 1 > maxCol) maxCol = p.col + 1;
739:   }
740:   const lines = [];
741:   for (let r = 1; r <= maxRow; r += 1) {
742:     const fields = [];
743:     for (let c = 0; c < maxCol && c < MAX_COLS; c += 1) {
744:       const cell = cells[colLetter(c) + r];
745:       fields.push(csvEscape(cell ? cell.value : ''));
746:     }
747:     lines.push(fields.join(','));
748:   }
749:   return lines.join('\n');
750: }
