797: // Դ cells �ṹ {raw, value}���ۺ�֧�� SUM/COUNT/AVERAGE����/�з��� + Grand Total
798: function pivotSummarize(sourceWs, start, end, summarizeBy, valueCol) {
799:   const a = parseRef(String(start));
800:   const b = parseRef(String(end));
801:   if (!a || !b) return { ok: false, message: 'Invalid pivot range' };
