803:   const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col);
804:   const r1 = Math.min(a.row, b.row) + 1, r2 = Math.max(a.row, b.row) + 1;
805:   const header = {}; // col(0-based) -> ��ͷ�ı�
806:   for (let c = c1; c <= c2; c += 1) header[c] = String(sourceWs.cells[colLetter(c) + r1]?.raw ?? '');
807:   // ������ r1+1..r2
808:   const rows = [];
809:   for (let r = r1 + 1; r <= r2; r += 1) {
810:     const row = {};
