832: // ����͸�ӱ� cells��{rowsKey->{colKey->agg}}, rowKey ���鱣������˳��
833: function buildPivotCells(meta, rowsField, colsField, valueField, summarizeBy) {
834:   const { header, rows } = meta;
835:   // �ֶ��кţ�����ͷ�ı�ƥ�䣨rowsField/colsField/valueField �Ǳ�ͷ����
836:   const colOf = (name) => { for (let c in header) if (header[c] === name) return Number(c); return null; };
837:   const rowCol = colOf(rowsField);
838:   const colCol = colOf(colsField);
839:   const valCol = colOf(valueField);
840:   console.log('[PIVOT-DIAG]', JSON.stringify({ rowCol, colCol, valCol, rows0: rows[0], summarizeBy }));
841:   if (rowCol === null || valCol === null) return { ok: false, message: 'pivot field is no longer available. select a new field.' };
842:   const rowOrder = [];
843:   const colOrder = [];
844:   const groups = {}; // rowKey -> {colKey -> {sum,count,n}}
845:   let grandSum = 0; // ȫ����ֵ�ۼƣ�AVERAGE �� Grand Total ��ȫԴ��ֵ��
846:   let grandN = 0;
847:   for (const row of rows) {
848:     const rk = String(row[rowCol]);
849:     const ck = colCol === null ? '__total__' : (String(row[colCol] ?? ''));
850:     if (!(rk in groups)) { groups[rk] = {}; rowOrder.push(rk); }
851:     const g = groups[rk];
852:     if (!(ck in g)) { g[ck] = { sum: 0, count: 0, n: 0 }; if (ck !== '__total__' && !colOrder.includes(ck)) colOrder.push(ck); }
853:     const v = pivotValue(row[valCol], summarizeBy);
854:     if (v === null) continue;
855:     g[ck].sum += v; g[ck].count += 1; g[ck].n += 1;
856:     grandSum += v; grandN += 1;
857:   }
858:   // ��װ��ά���������/�� Grand Total��
859:   const cells = {};
860:   const aggOf = (rk, ck) => {
861:     const g = groups[rk] && groups[rk][ck];
862:     if (!g) return 0;
863:     return summarizeBy === 'AVERAGE' ? (g.n ? g.sum / g.n : 0) : g.sum;
864:   };
865:   if (colOrder.length === 0) {
866:     // ��ά�ȣ�A=���ֶ�, B=�ۺ���ͷ(SUM of X), ������ B=�ۺ�ֵ, ĩ�� Grand Total
867:     cells.A1 = { raw: rowsField, value: rowsField };
868:     cells.B1 = { raw: `${summarizeBy} of ${valueField}`, value: `${summarizeBy} of ${valueField}` };
869:     let r = 2;
870:     for (const rk of rowOrder) {
871:       cells['A' + r] = { raw: rk, value: rk };
872:       const v = aggOf(rk, '__total__');
873:       cells['B' + r] = { raw: formatCellValue(v, summarizeBy), value: formatCellValue(v, summarizeBy) };
874:       r += 1;
875:     }
876:     let grand = 0;
877:     for (const rk of rowOrder) grand += aggOf(rk, '__total__');
878:     if (summarizeBy === 'AVERAGE') grand = grandN ? grandSum / grandN : 0; // AVERAGE �� Grand Total = ȫԴ��ֵ
879:     cells['A' + r] = { raw: 'Grand Total', value: 'Grand Total' };
880:     cells['B' + r] = { raw: formatCellValue(grand, summarizeBy), value: formatCellValue(grand, summarizeBy) };
881:     return { ok: true, cells, nextRow: r };
882:   }
883:   // ��ά��A=���ֶ�, B..=���ֶ�ֵ, ĩ�� Grand Total, ĩ�� Grand Total
884:   cells.A1 = { raw: rowsField, value: rowsField };
885:   let colIdx = 1;
886:   const colLetters = [];
887:   for (const ck of colOrder) { colLetters.push(colLetter(colIdx)); cells[colLetter(colIdx) + 1] = { raw: ck, value: ck }; colIdx += 1; }
888:   colLetters.push(colLetter(colIdx)); cells[colLetter(colIdx) + 1] = { raw: 'Grand Total', value: 'Grand Total' };
889:   let r = 2;
890:   for (const rk of rowOrder) {
891:     cells['A' + r] = { raw: rk, value: rk };
892:     let rowTotal = 0;
893:     let ci = 1;
894:     for (const ck of colOrder) {
895:       const v = aggOf(rk, ck);
896:       rowTotal += v;
897:       cells[colLetter(ci) + r] = { raw: formatCellValue(v, summarizeBy), value: formatCellValue(v, summarizeBy) };
898:       ci += 1;
899:     }
900:     cells[colLetter(ci) + r] = { raw: formatCellValue(rowTotal, summarizeBy), value: formatCellValue(rowTotal, summarizeBy) };
901:     r += 1;
902:   }
903:   cells['A' + r] = { raw: 'Grand Total', value: 'Grand Total' };
904:   let ci = 1;
905:   let grand = 0;
906:   for (const ck of colOrder) {
907:     let colSum = 0;
908:     for (const rk of rowOrder) colSum += aggOf(rk, ck);
909:     grand += colSum;
910:     cells[colLetter(ci) + r] = { raw: formatCellValue(colSum, summarizeBy), value: formatCellValue(colSum, summarizeBy) };
911:     ci += 1;
912:   }
913:   cells[colLetter(ci) + r] = { raw: formatCellValue(grand, summarizeBy), value: formatCellValue(grand, summarizeBy) };
914:   return { ok: true, cells, nextRow: r };
915: }
