1: #!/usr/bin/env python3
2: """Development checks with owned resources and reusable successful evidence.
3: 
4: Final controller acceptance deliberately does not consume this cache. No official
5: or external test input, arbitrary commands, network lookup or model call is used.
6: """
7: import argparse
8: from contextlib import contextmanager
9: from hashlib import sha256
10: import json
11: import os
12: from pathlib import Path
13: import shutil
14: import signal
15: import socket
16: import subprocess
17: import sys
18: import tempfile
19: import time
20: from urllib.request import build_opener, ProxyHandler
21: from urllib.error import URLError
22: 
23: EXCLUDED = {'.git', '.arc', '.codex', 'node_modules', 'dist', 'build', 'coverage',
24:             'test-results', 'playwright-report', '__pycache__', '.arc-test-db'}
25: TARGETS = ('build', 'frontend', 'backend', 'e2e')
